#[cfg(test)]mod appearance27_world_binding_development_tests {
 use super::*;
 fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for k in["world","start","status","actor","bot"]{let h=f["packets"][k].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w}
 fn shape(id:u32,gfx:u16,family:u8)->Vec<u8>{let mut b=vec![39];b.extend(id.to_le_bytes());b.extend(gfx.to_le_bytes());b.push(family);b}
 fn action(id:u32,value:u8)->Vec<u8>{let mut b=vec![32];b.extend(id.to_le_bytes());b.push(value);b}
 #[test]fn malformed_shape_is_atomic_and_orphan_never_creates_an_actor(){let mut w=world();let id=w.own_actor().unwrap().id;let b=shape(id,8859,4);for bad in [b[..7].to_vec(),{let mut a=b.clone();a.push(0);a},shape(0,8859,4)]{let before=serde_json::to_value(&w).unwrap();assert!(w.accept(&bad).is_err());assert_eq!(serde_json::to_value(&w).unwrap(),before);}let n=w.actors.len();let orphan=w.orphan_updates;assert!(w.accept(&shape(0x81234567,8859,4)).unwrap());assert_eq!(w.actors.len(),n);assert_eq!(w.orphan_updates,orphan+1);}
 #[test]fn shape_and_following_action_heading_keep_wire_order_without_hp_or_cast_ack(){let mut w=world();let own=w.own_actor().unwrap().clone();let authority=(w.hp,w.mp,w.own_cast_packets,own.incarnation);w.accept(&action(own.id,18)).unwrap();w.accept(&shape(own.id,8859,4)).unwrap();w.accept(&action(own.id,19)).unwrap();let mut heading=vec![28];heading.extend(own.id.to_le_bytes());heading.push(7);w.accept(&heading).unwrap();let a=w.own_actor().unwrap();let tape=a.appearance.as_ref().unwrap();assert_eq!(tape.initial.body.graphics,own.graphics);assert!(tape.entries.iter().zip(tape.entries.iter().skip(1)).all(|(a,b)|a.sequence<b.sequence));assert!(matches!(tape.entries[tape.entries.len()-3].operation,super::super::native_appearance27::Operation::Appearance(_)));assert!(matches!(tape.entries[tape.entries.len()-2].operation,super::super::native_appearance27::Operation::ServerAction{action:19,..}));assert!(matches!(tape.entries.back().unwrap().operation,super::super::native_appearance27::Operation::Heading(7)));assert_eq!((a.graphics,a.walk_action),(8859,4));assert_eq!((w.hp,w.mp,a.incarnation),(authority.0,authority.1,authority.3));assert_eq!(w.own_cast_packets,authority.2+2);}
 #[test]fn new_life_put_and_map_retire_old_shape_tape(){let mut w=world();let id=w.own_actor().unwrap().id;w.accept(&shape(id,8859,4)).unwrap();let mut resurrect=vec![17];resurrect.extend(id.to_le_bytes());resurrect.push(0);resurrect.extend(2_u32.to_le_bytes());resurrect.extend(240_u16.to_le_bytes());let old=w.own_actor().unwrap().incarnation;w.accept(&resurrect).unwrap();assert!(w.own_actor().unwrap().appearance.is_none());assert_ne!(w.own_actor().unwrap().incarnation,old);w.accept(&shape(id,8859,4)).unwrap();let map=w.map_id.unwrap();let mut b=vec![40];b.extend(map.to_le_bytes());b.push(0);w.accept(&b).unwrap();assert!(w.actors.is_empty());}
}
